#[test]
fn test_replay_server_namespace_bindings() {
    // The BAML-implemented replay server lives in the `replay` namespace
    // (ns_replay/). Both invocation entry points get sync + async siblings.
    use baml_sdk::replay;

    let _ = replay::replay_serve_until_shutdown;
    let _ = replay::replay_serve_until_shutdown_async;
    let _ = replay::replay_serve_detached;
    let _ = replay::replay_serve_detached_async;
}

// ---------------------------------------------------------------------------
// Shorthand-client api_key wiring
//
// `client "openai/gpt-4o-mini"` and `client "anthropic/..."` lower into
// the `from_shorthand` rust syscall, which has no syntactic api_key
// binding — there's no `env.OPENAI_API_KEY` in the source for the
// compiler to thread. The rust path must populate `api_key` itself from
// the provider's canonical env var (OPENAI_API_KEY / ANTHROPIC_API_KEY).
// These tests pin that contract by inspecting the auth header on the
// `Request` returned by `*$build_request`, which is the last station
// before bytes hit the network.
//
// ADAPTATION(rust): python's `monkeypatch.setenv` scopes each variable to
// its test; Rust has no fixture equivalent, so the variables are set
// process-wide — the two OPENAI_API_KEY tests would race under the parallel
// test runner and may need serialization at flip time.
// ---------------------------------------------------------------------------

#[test]
fn test_extract_resume_build_request_includes_openai_api_key() {
    use baml_sdk::lorem;

    // SAFETY: mutating the process environment is unsynchronized global
    // state (why edition 2024 marks it `unsafe`); this suite owns the
    // variable — see the section note on the cross-test race.
    unsafe { std::env::set_var("OPENAI_API_KEY", "sk-openai-shorthand-test") };

    let request = lorem::ExtractResume__build_request("Some resume text".to_string()).unwrap();
    // Authorization header is added by `auth_openai`; case-insensitive
    // because reqwest may normalize the casing on the wire, but the
    // build_request output preserves what we set.
    let headers_lower: baml_bridge::Map<String, String> = request
        .headers
        .iter()
        .map(|(k, v)| (k.to_lowercase(), v.clone()))
        .collect();
    assert!(
        headers_lower.contains_key("authorization"),
        "shorthand openai client did not set authorization header: {:?}",
        request.headers
    );
    assert_eq!(
        headers_lower["authorization"], "Bearer sk-openai-shorthand-test",
        "unexpected authorization header"
    );
}

#[test]
fn test_streaming_extract_build_request_includes_openai_api_key() {
    use baml_sdk::lorem;

    // `openai-responses` shares the OPENAI_API_KEY convention with
    // `openai`, and auth_openai routes both through the same Bearer
    // header.
    // SAFETY: same process-global env reasoning as the sibling tests.
    unsafe { std::env::set_var("OPENAI_API_KEY", "sk-openai-responses-test") };

    let request =
        lorem::StreamingExtract__build_request("Some text to summarize".to_string()).unwrap();
    let headers_lower: baml_bridge::Map<String, String> = request
        .headers
        .iter()
        .map(|(k, v)| (k.to_lowercase(), v.clone()))
        .collect();
    assert!(
        headers_lower.contains_key("authorization"),
        "shorthand openai-responses client did not set authorization header: {:?}",
        request.headers
    );
    assert_eq!(
        headers_lower["authorization"], "Bearer sk-openai-responses-test",
        "unexpected authorization header"
    );
}

#[test]
fn test_classify_sentiment_build_request_includes_anthropic_api_key() {
    use baml_sdk::ipsum;

    // SAFETY: same process-global env reasoning as the sibling tests.
    unsafe { std::env::set_var("ANTHROPIC_API_KEY", "sk-ant-shorthand-test") };

    let request = ipsum::ClassifySentiment__build_request("I love this!".to_string()).unwrap();
    let headers_lower: baml_bridge::Map<String, String> = request
        .headers
        .iter()
        .map(|(k, v)| (k.to_lowercase(), v.clone()))
        .collect();
    assert!(
        headers_lower.contains_key("x-api-key"),
        "shorthand anthropic client did not set x-api-key header: {:?}",
        request.headers
    );
    assert_eq!(
        headers_lower["x-api-key"], "sk-ant-shorthand-test",
        "unexpected x-api-key header"
    );
}
